    const channel = document.querySelector('yt-formatted-string.ytd-channel-name a')?.innerText || '';
    const subscriberCount = document.querySelector('#owner-sub-count')?.innerText || '';
    const viewCount = document.querySelector('yt-formatted-string[aria-label*="views"]')?.ariaLabel || '';
    const date = document.querySelector('yt-formatted-string[aria-label*="ago"]')?.ariaLabel || '';
