        const author = comment.querySelector('#author-text')?.innerText || '';
        const text = comment.querySelector('#content-text')?.innerText || '';
        const likes = comment.querySelector('#vote-count-middle')?.innerText || '';
        const time = comment.querySelector('yt-formatted-string.published-time-text a')?.innerText || '';
